:"audiences","where":{"slug":"data-ownership-seekers"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:2101969ea5974385f2e3eea5301359786008df1bb97335ad413a470630cd9dcf"}}}}},{"table":"product_audience_evidence","keys":["product_id","audience_id","claim_evidence_id"],"before":{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"offline-first-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:89d8ef318cb205adea37621f45bc71ca7e4d466ccafedef321cc7b020745daec"}}}},"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"offline-first-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:89d8ef318cb205adea37621f45bc71ca7e4d466ccafedef321cc7b020745daec"}}}}},{"table":"product_audience_evidence","keys":["product_id","audience_id","claim_evidence_id"],"before":{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"privacy-conscious-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:d56a560f15146ef96a1c28ee03341455095b2f29494565a85450dfd9b652e31e"}}}},"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"privacy-conscious-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:d56a560f15146ef96a1c28ee03341455095b2f29494565a85450dfd9b652e31e"}}}}}],"guardCounts":[{"table":"product_attributes","slug":"affine","before":14,"after":14},{"table":"product_attributes","slug":"appflowy","before":14,"after":14},{"table":"product_attributes","slug":"anytype","before":14,"after":14},{"table":"product_anchors","slug":"affine","before":1,"after":1},{"table":"product_anchors","slug":"appflowy","before":1,"after":1},{"table":"product_anchors","slug":"anytype","before":1,"after":1},{"table":"product_problems","slug":"affine","before":3,"after":3},{"table":"product_problems","slug":"appflowy","before":3,"after":3},{"table":"product_problems","slug":"anytype","before":2,"after":2},{"table":"product_audiences","slug":"affine","before":3,"after":3},{"table":"product_audiences","slug":"appflowy","before":3,"after":3},{"table":"product_audiences","slug":"anytype","before":3,"after":3},{"table":"product_attribute_evidence","slug":"affine","before":19,"after":21},{"table":"product_attribute_evidence","slug":"appflowy","before":17,"after":18},{"table":"product_attribute_evidence","slug":"anytype","before":9,"after":12},{"table":"product_anchor_evidence","slug":"affine","before":4,"after":4},{"table":"product_anchor_evidence","slug":"appflowy","before":5,"after":5},{"table":"product_anchor_evidence","slug":"anytype","before":3,"after":3},{"table":"product_problem_evidence","slug":"affine","before":3,"after":3},{"table":"product_problem_evidence","slug":"appflowy","before":3,"after":3},{"table":"product_problem_evidence","slug":"anytype","before":2,"after":2},{"table":"product_audience_evidence","slug":"affine","before":3,"after":3},{"table":"product_audience_evidence","slug":"appflowy","before":3,"after":3},{"table":"product_audience_evidence","slug":"anytype","before":3,"after":3}]}$payload$::jsonb;
  op jsonb; raw_row jsonb; row_data jsonb; replacement jsonb; own jsonb;
  t text; cols text; conflict_cols text; key_condition text; match_condition text;
  assignments text; changed text; statement text; allowed boolean; bad boolean; found_row boolean;
  route_slug text; route_id uuid; wanted text[]; desired_keys text[]; prefix text;
  expected integer; actual integer; where_data jsonb; fragment_id uuid;
  k text; v jsonb; target_table text; target_key text; target_value text; resolved_id uuid; input_data jsonb;
BEGIN
  PERFORM set_config('lock_timeout','10s',true);
  PERFORM pg_advisory_xact_lock(7232003);
  LOCK TABLE software_discovery.evidence_sources,software_discovery.anchors,software_discovery.attributes,software_discovery.problems,software_discovery.audiences,software_discovery.products,software_discovery.product_attributes,software_discovery.product_anchors,software_discovery.product_problems,software_discovery.product_audiences,software_discovery.claim_evidence,software_discovery.product_attribute_evidence,software_discovery.product_anchor_evidence,software_discovery.product_problem_evidence,software_discovery.product_audience_evidence,software_discovery.escape_routes,software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
  own=data->'ownership';
  IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('obsidian','things','omnifocus','2do','affine','anytype','appflowy','gimp','krita','paint-net') AND status='published')<>10 THEN RAISE EXCEPTION 'PR5.19 published prerequisites mismatch'; END IF;
  IF (SELECT count(*) FROM software_discovery.escape_routes WHERE slug IN ('todoist-alternatives-with-a-one-time-purchase','offline-notion-alternatives','photoshop-alternatives-without-a-subscription') AND status='published' AND editorially_approved)<>3 THEN RAISE EXCEPTION 'PR5.19 accepted routes mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='notion-alternatives-without-ai' AND (status<>'draft' OR editorially_approved)) THEN RAISE EXCEPTION 'PR5.19 no-AI route already exposed; fresh review required'; END IF;
  IF EXISTS(SELECT 1 FROM software_discovery.escape_route_products m JOIN software_discovery.products p ON p.id=m.product_id JOIN software_discovery.escape_routes r ON r.id=m.escape_route_id WHERE p.slug IN ('affine','appflowy','anytype') AND r.status='published' AND r.editorially_approved AND r.slug<>'offline-notion-alternatives') THEN RAISE EXCEPTION 'PR5.19 unexpected approved target route exposure'; END IF;
  FOR op IN SELECT value FROM jsonb_array_elements(data->'guardRows') LOOP
    t=op->>'table';input_data=op->'after';row_data='{}';bad=false;
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        resolved_id=NULL;EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO resolved_id USING target_value;
        IF resolved_id IS NULL THEN bad=true; END IF;v=coalesce(to_jsonb(resolved_id),'null'::jsonb);
      END IF;
      row_data=row_data||jsonb_build_object(k,v);
    END LOOP;
    IF bad THEN
      IF op->'before'<>'null'::jsonb THEN RAISE EXCEPTION 'PR5.19 required reference missing'; END IF;
      CONTINUE;
    END IF;
    SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',value,value),' AND ') INTO key_condition FROM jsonb_array_elements_text(op->'keys');
    SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ') INTO match_condition FROM jsonb_object_keys(row_data) AS keys(key);
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s), EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s AND %s)',t,t,key_condition,t,t,key_condition,match_condition) INTO found_row,allowed USING row_data;
    IF NOT found_row AND op->'before'<>'null'::jsonb THEN RAISE EXCEPTION 'PR5.19 required baseline missing: %',t; END IF;
    IF found_row AND NOT allowed THEN
      IF op->'before'='null'::jsonb THEN RAISE EXCEPTION 'PR5.19 unexpected new evidence drift: %',t; END IF;
      input_data=op->'before';where_data='{}';
      FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
        IF v ? '$ref' THEN
          target_table=v->'$ref'->>'table';SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
          EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;v=to_jsonb(resolved_id);
        END IF;
        where_data=where_data||jsonb_build_object(k,v);
      END LOOP;
      SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ') INTO match_condition FROM jsonb_object_keys(where_data) AS keys(key);
      EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s)',t,t,match_condition) INTO allowed USING where_data;
      IF NOT allowed THEN RAISE EXCEPTION 'PR5.19 baseline drift: %',t; END IF;
    END IF;
  END LOOP;
  FOR op IN SELECT value FROM jsonb_array_elements(data->'guardCounts') LOOP
    SELECT id INTO STRICT resolved_id FROM software_discovery.products WHERE slug=op->>'slug';
    EXECUTE format('SELECT count(*) FROM software_discovery.%I WHERE product_id=$1',op->>'table') INTO actual USING resolved_id;
    IF actual<>(op->>'before')::integer AND actual<>(op->>'after')::integer THEN RAISE EXCEPTION 'PR5.19 relationship/evidence set drift: %/%',op->>'table',op->>'slug'; END IF;
    expected=0;
    FOR replacement IN SELECT value FROM jsonb_array_elements(data->'guardRows') g WHERE g->>'table'=op->>'table' AND g->'after'->'product_id'->'$ref'->'where'->>'slug'=op->>'slug' LOOP
      row_data='{}';bad=false;
      FOR k,v IN SELECT * FROM jsonb_each(replacement->'after') LOOP
        IF v ? '$ref' THEN
          target_table=v->'$ref'->>'table';SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
          resolved_id=NULL;EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO resolved_id USING target_value;
          IF resolved_id IS NULL THEN bad=true; END IF;v=coalesce(to_jsonb(resolved_id),'null'::jsonb);
        END IF;
        row_data=row_data||jsonb_build_object(k,v);
      END LOOP;
      IF NOT bad THEN
        SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',value,value),' AND ') INTO key_condition FROM jsonb_array_elements_text(replacement->'keys');
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s)',op->>'table',op->>'table',key_condition) INTO found_row USING row_data;
        IF found_row THEN expected=expected+1; END IF;
      END IF;
    END LOOP;
    IF actual<>expected THEN RAISE EXCEPTION 'PR5.19 unreviewed relationship/evidence identity'; END IF;
  END LOOP;

  FOR replacement IN SELECT value FROM jsonb_array_elements(data->'routeMembershipReplacements') LOOP
    route_slug=replacement->'where'->'escape_route_id'->'$ref'->'where'->>'slug';
    IF NOT (own->'routes' ? route_slug) THEN
      SELECT id INTO route_id FROM software_discovery.escape_routes WHERE slug=route_slug;
      IF route_id IS NOT NULL THEN
        SELECT coalesce(array_agg(value ORDER BY value),'{}') INTO wanted FROM jsonb_array_elements_text(replacement->'desiredProductSlugs');
        IF wanted IS DISTINCT FROM (SELECT coalesce(array_agg(p.slug ORDER BY p.slug),'{}') FROM software_discovery.escape_route_products m JOIN software_discovery.products p ON p.id=m.product_id WHERE m.escape_route_id=route_id) THEN RAISE EXCEPTION 'Existing route membership differs; ownership required: %',route_slug; END IF;
      END IF;
    END IF;
  END LOOP;
  FOR op IN SELECT value FROM jsonb_array_elements(data->'tables') LOOP
    t=op->>'table';
    IF t NOT IN ('evidence_sources','anchors','attributes','problems','audiences','products','product_attributes','product_anchors','product_problems','product_audiences','claim_evidence','product_attribute_evidence','product_anchor_evidence','product_problem_evidence','product_audience_evidence','escape_routes','escape_route_products') THEN RAISE EXCEPTION 'Invalid table'; END IF;
    SELECT string_agg(format('%I',value),',') INTO conflict_cols FROM jsonb_array_elements_text(op->'conflictColumns');
    actual=0; expected=jsonb_array_length(op->'rows');
    FOR raw_row IN SELECT value FROM jsonb_array_elements(op->'rows') LOOP
  input_data=raw_row; row_data='{}';
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';
        IF target_table NOT IN ('products','anchors','attributes','problems','audiences','escape_routes','evidence_sources','claim_evidence') THEN RAISE EXCEPTION 'Invalid reference table'; END IF;
        SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        IF target_key NOT IN ('slug','seed_key') THEN RAISE EXCEPTION 'Invalid reference key'; END IF;
        EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;
        v=to_jsonb(resolved_id);
      END IF;
      row_data=row_data||jsonb_build_object(k,v);
    END LOOP;
      SELECT string_agg(format('%I',key),',' ORDER BY key),string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ' ORDER BY key) INTO cols,match_condition FROM jsonb_object_keys(row_data) AS keys(key);
      SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',value,value),' AND ') INTO key_condition FROM jsonb_array_elements_text(op->'conflictColumns');
      allowed=CASE
        WHEN t='evidence_sources' THEN own->'sources' ? (raw_row->>'seed_key')
        WHEN t='products' THEN own->'products' ? (raw_row->>'slug')
        WHEN t='escape_routes' THEN own->'routes' ? (raw_row->>'slug')
        WHEN t='escape_route_products' THEN own->'routes' ? (raw_row->'escape_route_id'->'$ref'->'where'->>'slug')
        WHEN raw_row ? 'product_id' THEN own->'products' ? (raw_row->'product_id'->'$ref'->'where'->>'slug')
        WHEN t IN ('anchors','attributes','problems','audiences') THEN own->'taxonomy'->t ? (raw_row->>'slug')
        ELSE false END;
      IF NOT coalesce(allowed,false) THEN
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s AND NOT (%s))',t,t,key_condition,match_condition) INTO bad USING row_data;
        IF bad THEN RAISE EXCEPTION 'Existing row differs; ownership required: %',t; END IF;
      END IF;
      SELECT string_agg(format('%I=EXCLUDED.%I',key,key),',' ORDER BY key),string_agg(format('target.%I IS DISTINCT FROM EXCLUDED.%I',key,key),' OR ' ORDER BY key) INTO assignments,changed FROM jsonb_object_keys(row_data) AS keys(key) WHERE NOT (op->'conflictColumns' ? key);
      statement=format('INSERT INTO software_discovery.%I AS target (%s) SELECT %s FROM jsonb_populate_record(NULL::software_discovery.%I,$1) source ON CONFLICT (%s) ',t,cols,cols,t,conflict_cols);
      IF assignments IS NULL OR t='claim_evidence' THEN statement=statement||'DO NOTHING';
      ELSE
        IF t IN ('evidence_sources','anchors','attributes','problems','audiences','products','product_attributes','escape_routes','escape_route_products') THEN assignments=assignments||',updated_at=now()'; END IF;
        statement=statement||format('DO UPDATE SET %s WHERE %s',assignments,changed);
      END IF;
      EXECUTE statement USING row_data;
      EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s)',t,t,match_condition) INTO found_row USING row_data;
      IF NOT found_row THEN RAISE EXCEPTION 'Stored row differs from seed: %',t; END IF;
      actual=actual+1;
    END LOOP;
    RAISE NOTICE 'Seed table %: % rows verified',t,actual;
  END LOOP;
  FOR replacement IN SELECT value FROM jsonb_array_elements(data->'evidenceReplacements') LOOP
    t=replacement->>'table';
    IF t NOT IN ('product_attribute_evidence','product_anchor_evidence','product_problem_evidence','product_audience_evidence') THEN RAISE EXCEPTION 'Invalid evidence table'; END IF;
    input_data=replacement->'where'; where_data='{}';
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';
        IF target_table NOT IN ('products','anchors','attributes','problems','audiences','escape_routes','evidence_sources','claim_evidence') THEN RAISE EXCEPTION 'Invalid reference table'; END IF;
        SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        IF target_key NOT IN ('slug','seed_key') THEN RAISE EXCEPTION 'Invalid reference key'; END IF;
        EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;
        v=to_jsonb(resolved_id);
      END IF;
      where_data=where_data||jsonb_build_object(k,v);
    END LOOP;
    SELECT string_agg(format('link.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ') INTO key_condition FROM jsonb_object_keys(where_data) AS keys(key);
    SELECT coalesce(array_agg(value),'{}') INTO desired_keys FROM jsonb_array_elements_text(replacement->'desiredFragmentKeys');
    prefix=replacement->'ownership'->>'fragmentSeedKeyPrefix';
    EXECUTE format('DELETE FROM software_discovery.%I link USING software_discovery.claim_evidence fragment,jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE link.claim_evidence_id=fragment.id AND %s AND left(fragment.seed_key,length($2))=$2 AND NOT(fragment.seed_key=ANY($3))',t,t,key_condition) USING where_data,prefix,desired_keys;
  END LOOP;
  FOR replacement IN SELECT value FROM jsonb_array_elements(data->'routeMembershipReplacements') LOOP
    input_data=replacement->'where'; where_data='{}';
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';
        IF target_table NOT IN ('products','anchors','attributes','problems','audiences','escape_routes','evidence_sources','claim_evidence') THEN RAISE EXCEPTION 'Invalid reference table'; END IF;
        SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        IF target_key NOT IN ('slug','seed_key') THEN RAISE EXCEPTION 'Invalid reference key'; END IF;
        EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;
        v=to_jsonb(resolved_id);
      END IF;
      where_data=where_data||jsonb_build_object(k,v);
    END LOOP;route_id=(where_data->>'escape_route_id')::uuid;
    SELECT coalesce(array_agg(value),'{}') INTO wanted FROM jsonb_array_elements_text(replacement->'desiredProductSlugs');
    DELETE FROM software_discovery.escape_route_products m WHERE m.escape_route_id=route_id AND NOT EXISTS(SELECT 1 FROM software_discovery.products p WHERE p.id=m.product_id AND p.slug=ANY(wanted));
    SELECT count(*) INTO actual FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
    IF actual<>cardinality(wanted) THEN RAISE EXCEPTION 'Route membership count mismatch'; END IF;
  END LOOP;
  RAISE SQLSTATE 'ZSR01' USING MESSAGE='Rehearsal only';
EXCEPTION WHEN SQLSTATE 'ZSR01' THEN
  RAISE NOTICE 'Rehearsal rolled back; no seed changes persisted';
END $import$;
